use crate::aap::caps::inference_llm;
use crate::aap::caps::types::{Category, Importance};

struct Node;

/// Upper bound the `ensures len(overview) <= 600` clause imposes. Enforced in
/// bytes, which bounds characters as well.
const OVERVIEW_MAX: usize = 600;

const SYSTEM: &str = "You write a short plain-text overview of a feed digest. \
Reply with prose only, no markup, at most 600 characters.";

fn category_name(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_name(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

/// Truncate to at most `max` bytes, cutting only at a character boundary.
fn bound_bytes(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

/// Civil date (YYYY-MM-DD, UTC) from Unix epoch seconds. Used only when the
/// run-info date is not already a 10-character ASCII date, so the `ensures`
/// on the output date holds regardless of what the producer sent.
fn date_from_unix_secs(secs: u64) -> String {
    let z = (secs / 86_400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + (if m <= 2 { 1 } else { 0 });
    if (0..=9999).contains(&y) {
        format!("{:04}-{:02}-{:02}", y, m, d)
    } else {
        "1970-01-01".to_string()
    }
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // The date published under: the run's own date when it is a 10-character
        // ASCII date, otherwise derived from the start instant.
        let date = if info.date.len() == 10 && info.date.is_ascii() {
            info.date
        } else {
            date_from_unix_secs(info.started)
        };

        // Material for the model: the kept items only. Titles and summaries are
        // adversarial text; they are passed as data in the prompt and never
        // change what this node is permitted to return.
        let mut prompt = String::new();
        prompt.push_str("Date: ");
        prompt.push_str(&date);
        prompt.push('\n');
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!(
                "- [{}/{}] {}: {}\n",
                category_name(e.category),
                importance_name(e.importance),
                e.title,
                e.summary,
            ));
        }

        let raw = inference_llm::infer(SYSTEM, &prompt, "digest");
        let overview = bound_bytes(raw, OVERVIEW_MAX);

        Digest {
            date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
